package org.sirius.biotech;
import android.content.*;
import android.provider.CalendarContract;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.sirius.biotech.data.*;
import java.util.*;
import static org.sirius.biotech.OriginalUi.*;

/** The retained session screen, information rows, question composer and poll-style rating route. */
final class OriginalSession {
    static View create(MainActivity a,int index)throws Exception{
        Context c=theme(a);EventRepository.Session item=a.sessions.get(index);LinearLayout root=scene(a,"session_view");toolbar(a,view(root,"toolbar"),"Session",()->a.show(a.scheduleReturn),"session_details",action->{if(action.equals("menu_item_add_to_calendar"))calendar(a,item);else ContentActions.favorite(a,"sessions",item.id,!a.saved(index),()->{});});text(root,"toolbarTitleView",a.tr("Session"));View header=view(root,"headerView");call(header,"setTitle",new Class<?>[]{String.class},item.title);List<View> pages=new ArrayList<>();List<String> titles=new ArrayList<>();
        FrameLayout info=new FrameLayout(c);inflate(c,"session_info_view",info);List<OriginalRecycler.Row> rows=new ArrayList<>();rows.add(parent->{View row=inflate(c,"session_time_item_view",parent,false);text(row,"valueView",item.time);return row;});if(!item.room.isEmpty())rows.add(parent->{View row=inflate(c,"session_location_item_view",parent,false);text(row,"titleView",item.room);row.setOnClickListener(v->a.show("Venue"));return row;});if(!item.track.isEmpty())rows.add(parent->{View row=inflate(c,"session_tag_item_view",parent,false);TextView value=firstText(row);value.setText(item.track);return row;});
        if(!item.description.isEmpty())rows.add(parent->{TextView description=labelView(c,item.description,16,a.ink);description.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(14));description.setLineSpacing(0,1.35f);android.text.util.Linkify.addLinks(description,android.text.util.Linkify.WEB_URLS);return description;});
        boolean found=false;for(int n=0;n<a.participants.size();n++){final int person=n;if(!OriginalPeople.speaks(a.participants.get(n),item))continue;found=true;rows.add(parent->OriginalPeople.row(a,person,false,null));}if(!found&&!item.speaker.isEmpty())rows.add(parent->{TextView value=labelView(c,item.speaker,16,a.ink);value.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(16));return value;});
        rows.add(parent->SessionRatingView.create(a,item.id,()->a.session(index)));list(view(info,"recyclerView"),1,rows);pages.add(info);titles.add(label(a,"Информация","Information"));pages.add(questions(a,index));titles.add(label(a,"Вопросы","Questions"));View pager=pager(c,view(header,"tabLayout"),pages,titles.toArray(new String[0]));ViewGroup host=(ViewGroup)view(root,"viewShifter");host.setAlpha(1);host.addView(pager,new FrameLayout.LayoutParams(-1,-1));a.sceneBack=()->a.show(a.scheduleReturn);return root;
    }
    static TextView firstText(View v){if(v instanceof TextView)return (TextView)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){TextView found=firstText(((ViewGroup)v).getChildAt(n));if(found!=null)return found;}return null;}
    static View questions(MainActivity a,int index)throws Exception{
        Context c=theme(a);EventRepository.Session session=a.sessions.get(index);ViewGroup page=constraint(c);inflate(c,"session_questions_view",page);View items=view(page,"recyclerView");visible(page,"progressView",false);visible(page,"completableProgressView",false);View composer=view(page,"input");EditText input=childInput(composer);input.setHint(label(a,"Ваш вопрос спикеру","Your question to the speaker"));call(composer,"setAnonymousButtonVisible",new Class<?>[]{boolean.class},false);call(composer,"setAttachmentButtonVisible",new Class<?>[]{boolean.class},false);final int owner=a.accountGeneration;String path="/sessions/"+android.net.Uri.encode(session.id)+"/questions";
        final Runnable[] refresh={null};refresh[0]=()->a.network.execute(()->{try{JSONArray all=new JSONArray();for(int offset=0;;offset+=100){JSONArray batch=a.api.request("GET",path+"?limit=100&offset="+offset,null).getJSONArray("items");for(int n=0;n<batch.length();n++)all.put(batch.get(n));if(batch.length()<100)break;}a.runOnUiThread(()->{if(owner!=a.accountGeneration)return;try{List<OriginalRecycler.Row> rows=new ArrayList<>();for(int n=0;n<all.length();n++){JSONObject q=all.getJSONObject(n);rows.add(parent->{LinearLayout row=new LinearLayout(c);row.setOrientation(1);row.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));row.addView(labelView(c,q.optString("text"),16,a.ink));String answer=q.optString("response");if(!answer.isEmpty())row.addView(labelView(c,answer,16,0xff356aff));return row;});}list(items,1,rows);visible(page,"recyclerView",!rows.isEmpty());visible(page,"placeholder",rows.isEmpty());}catch(Exception e){failed(a,e);}});}catch(Exception ignored){}});
        call(composer,"setListener",new Class<?>[]{cls("com.eventicious.messaging.q")},java.lang.reflect.Proxy.newProxyInstance(OriginalSession.class.getClassLoader(),new Class<?>[]{cls("com.eventicious.messaging.q")},(p,m,args)->{if(m.getName().equals("a")){call(composer,"setSendButtonEnabled",new Class<?>[]{boolean.class},!input.getText().toString().trim().isEmpty());}if(m.getName().equals("b")&&args!=null){String text=String.valueOf(args[0]).trim();if(!text.isEmpty()){call(composer,"setSendButtonEnabled",new Class<?>[]{boolean.class},false);a.network.execute(()->{try{a.api.request("POST",path,new JSONObject().put("text",text));a.runOnUiThread(()->{if(owner==a.accountGeneration){input.setText("");refresh[0].run();}});}catch(Exception e){a.runOnUiThread(()->a.toast("Could not send question. Please retry."));}});}}return null;}));view(page,"refreshButton").setOnClickListener(v->refresh[0].run());refresh[0].run();return page;
    }
    static EditText childInput(View root){if(root instanceof EditText)return (EditText)root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){EditText found=childInput(((ViewGroup)root).getChildAt(n));if(found!=null)return found;}return null;}
    static void calendar(MainActivity a,EventRepository.Session session){try{JSONObject raw=((ServerRepository)a.repository).raw("sessions",session.id);java.time.LocalDate date=java.time.LocalDate.parse(raw.optString("date"));java.time.LocalTime start=java.time.LocalTime.parse(raw.optString("start_time")),end=java.time.LocalTime.parse(raw.optString("end_time"));a.startActivity(new Intent(Intent.ACTION_INSERT).setData(CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,session.title).putExtra(CalendarContract.Events.EVENT_LOCATION,session.room).putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,date.atTime(start).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()).putExtra(CalendarContract.EXTRA_EVENT_END_TIME,date.atTime(end).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()));}catch(Exception e){a.toast("Calendar app is unavailable");}}
}
